import React from 'react';
import { Link } from 'gatsby';
import { Helmet } from 'react-helmet';
import type { Theme } from '../types';
import { DARK, LIGHT } from '../data';
import { themeRef } from '../components/scene';
import { usePersistentTheme } from '../hooks/usePersistentTheme';
import { Layout } from '../components/Layout';
// import { useVisitCounter } from '../hooks/useVisitCounter';
import loadable from '@loadable/component';

const ThreeCanvas = loadable(
  () =>
    import('../components/scene').then((mod) => ({ default: mod.ThreeCanvas })),
  { ssr: false },
);

export default function NotFoundPage() {
  const [isLight, toggle] = usePersistentTheme();
  //   useVisitCounter();
  const t: Theme = isLight ? LIGHT : DARK;

  themeRef.current = t;

  const mono = 'DM Mono, monospace';

  return (
    <>
      <Helmet>
        <html lang='en' />
        <title>404 · Sanjeera Di</title>
        <link rel='icon' href='/favicon.ico' />
        <link rel='shortcut icon' href='/favicon.ico' />
        <meta name='robots' content='noindex' />
      </Helmet>

      <Layout
        t={t}
        isLight={isLight}
        toggle={toggle}
        background={<ThreeCanvas />}
      >
        <main
          className='cv-inner'
          style={{
            minHeight: '100vh',
            display: 'flex',
            alignItems: 'center',
            padding: '120px 48px 80px',
          }}
        >
          <section
            style={{
              width: '100%',
              maxWidth: 760,
              padding: '40px 0',
            }}
          >
            <div
              style={{
                fontSize: 11,
                letterSpacing: '0.2em',
                textTransform: 'uppercase',
                color: t.purple,
                marginBottom: 20,
                fontFamily: mono,
              }}
            >
              Page not found
            </div>

            <h1
              style={{
                fontFamily: 'Syne, sans-serif',
                fontSize: 'clamp(56px, 10vw, 118px)',
                fontWeight: 800,
                lineHeight: 0.9,
                letterSpacing: '-0.04em',
                color: t.text,
                marginBottom: 24,
              }}
            >
              404
              <br />
              <span
                style={{
                  color: 'transparent',
                  WebkitTextStroke: `1px ${t.heroStroke}`,
                }}
              >
                Lost route
              </span>
            </h1>

            <p
              style={{
                maxWidth: 540,
                fontSize: 14,
                color: t.text2,
                lineHeight: 1.8,
                marginBottom: 36,
                fontFamily: mono,
              }}
            >
              The page you requested does not exist, may have moved, or the URL
              is malformed. The rest of the portfolio is intact.
            </p>

            <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
              <Link
                to='/'
                style={{
                  fontFamily: mono,
                  fontSize: 12,
                  letterSpacing: '0.08em',
                  padding: '14px 32px',
                  background: t.purple,
                  color: '#fff',
                  borderRadius: 4,
                  textDecoration: 'none',
                  display: 'inline-block',
                }}
              >
                Return home
              </Link>
              <a
                href='mailto:hello@sanjdi.com'
                style={{
                  fontFamily: mono,
                  fontSize: 12,
                  letterSpacing: '0.08em',
                  padding: '14px 32px',
                  background: 'transparent',
                  color: t.text2,
                  border: `1px solid ${t.border2}`,
                  borderRadius: 4,
                  textDecoration: 'none',
                }}
              >
                Report broken link
              </a>
            </div>
          </section>
        </main>
      </Layout>
    </>
  );
}
